  "payment.transparency.title": "100% Прозрачность",
  "payment.transparency.hint": "Нажми на категорию, чтобы узнать детали.",
  "payment.transparency.eyebrow": "Куда идут деньги?",
  "transparency.part.development": "Развитие",
  "transparency.part.affiliate": "Сообщество",
  "transparency.part.directHelp": "Спасение",
  "transparency.part.hekthorBowl": "Миска Hekthor",
  "transparency.part.development.note": "Строим нацию и финансируем всё, на чём она держится, — людей, которые двигают DOGYPT вперёд, и стоящие за ними сервисы, инструменты и серверы. Это двигатель движения, и каждый расход до копейки будет задокументирован и опубликован открыто.",
  "transparency.part.affiliate.note": "Не реклама — люди. Это идёт прямиком на счета догиптян, которые несут веру дальше, и выплачивается в BONES: потрать их позже внутри DOGYPT или пожертвуй собакам в беде. Мы вкладываемся в стаю и никогда — в дорогой маркетинг: стая разносит весть куда лучше.",
  "transparency.part.directHelp.note": "Прямо собакам в беде — приютам, на корм, счета от ветеринара и спасательные миссии. Без посредников и накладных расходов: эта доля идёт туда, где страдание, и каждая копейка задокументирована, подтверждена чеком и открыта всей стае.",
  "transparency.part.hekthorBowl.note": "Пёс-основатель, с которого всё началось. Эта доля — прозрачное вознаграждение для Hekthor и его хозяина, попросту их зарплата. Их цель — стать миллионерами: миллион собак в стае. Без Hekthor DOGYPT никогда бы не появился — эта миска и есть спасибо.",
  "legal.eyebrow": "DOGYPT · Legal",
  "legal.motto": "DOGYPT · Верим в пса",
