  'entry.criteria.community.body': 'Мы — любители собак с целью. Поодиночке каждый из нас способен изменить немногое, вместе — нашей силе нет предела.',
  'entry.criteria.symbol.title': 'Символ',
  'entry.criteria.symbol.body': 'У каждой веры есть свой знак. Наш — heroglyph: уникальный священный символ для каждой собаки, понятный на любом языке и в любом уголке мира.',
  'entry.criteria.ritual.title': 'Ритуал',
  'entry.criteria.ritual.body': 'Прогулка. Ежедневная терапия, что держит в форме тело и разум — а с ними и душу. Древнейший ритуал, который мы уже соблюдаем без напоминаний.',
  'entry.criteria.vision.title': 'Видение',
  'entry.criteria.vision.body': 'Возвысить связь между человеком и собакой — и бороться за уважение и лучшую жизнь, которых заслуживает каждая собака.',
