  "pack.cal.life.tgtPre": "Цель:",
  "pack.cal.life.tgtBody": "до пяти лишних лет, которые может добавить холистическая забота — стройность, движение по пересечённой местности, зубы, сон и как можно меньше ненужной химии.",
  "pack.cal.life.tgtSrc": "Грубая оценка, не обещание. Измерено из этого пока одно: сама по себе стройность добавила лабрадорам 1,8 года (Purina Life Span Study, JAVMA 2002).",
  "pack.cal.life.intro": "Ниже — вся жизнь твоей собаки в блоках. Один блок = одна неделя, одна строка = один год. С одной стороны это пугает, с другой — именно напоминание о том, что нужно использовать каждый момент и не откладывать дела.",
