  "pack.cal.life.rec.pebbles.exact": "22 года 189 дней",
  "pack.cal.life.recSince": "с {year}",
  "pack.cal.life.tip.weight.title": "Стройность — единственное, что доказано",
  "pack.cal.life.tip.weight.body": "Из всего, что можно сделать для собаки, у одной вещи самое твёрдое доказательство влияния на продолжительность жизни: не давать ей набрать вес. Разница между стройной и слегка полной собакой — это годы, не месяцы. Ребра должны прощупываться без нажима.",
  "pack.cal.life.tip.move.title": "Движение по настоящей местности, а не круг вокруг дома",
  "pack.cal.life.tip.move.body": "Неровная поверхность держит в тонусе суставы, мышцы и голову. Каждая записанная поездка превращается на этой сетке в тёмную неделю — а тёмные недели это единственное, на что ты реально можешь повлиять.",
  "pack.cal.life.tip.food.title": "Еда, которую собака узнаёт как еду",
  "pack.cal.life.tip.food.body": "Чем меньше шагов между сырым продуктом и миской, тем меньше вещей может испортиться по пути. Сухой корм не грех, но и не рацион — это сокращённый путь.",
  "pack.cal.life.tip.chem.title": "Химия только тогда, когда она реально нужна",
  "pack.cal.life.tip.chem.body": "Круглогодичные противопаразитарные, наркоз для удобства и антибиотики «на всякий случай» — это решения, а не рутина. Спрашивай о каждом из них: что случится, если я этого не сделаю? Там, где ответ «ничего», не делай.",
  "pack.cal.life.tip.stress.title": "Покой считается так же, как движение",
  "pack.cal.life.tip.stress.body": "Собака, которая всегда начеку, сжигает тело изнутри. Непрерванный сон, предсказуемый день и тишина после нагрузки — это не лень, это часы, в которые тело себя восстанавливает.",
  "pack.cal.life.tip.protocol.title": "Протокол вместо панического бега к ветеринару",
  "pack.cal.life.tip.protocol.body": "У дегельминтизации, копрологии и анализа крови есть свои окна в календаре. Собака, которой дважды в год проверяют кровь, не лечится — она предупреждает болезнь.",
  "pack.cal.life.tip.joints.title": "Суставы решаются ДО того, как начинают болеть",
  "pack.cal.life.tip.joints.body": "Твоя собака уже в сениорском возрасте. Суставный курс имеет окно в календаре с ноября — не потому, что она хромает, а чтобы этого не случилось.",
  "pack.cal.life.size.toy": "Карликовые",
