  "pack.nature.balance.title": "Происходит сейчас что-нибудь?",
  "pack.nature.balance.body": "Конституция твоей собаки задана на всю жизнь, но может выйти из равновесия. Отметь всё, что подходит — сколько хочешь или вообще ничего.",
  "pack.nature.balance.none": "Ничего из списка? Оставь пустым и продолжай — это лучший ответ, какой есть.",
