  "pack.nature.special.body": "Эти четыре роли стоят НАД основной. У большинства собак нет ни одной — это нормально.",
  "pack.nature.special.cta": "Показать результат",
  "pack.nature.result.saved": "Сохранено на карту твоей собаки",
