  "pack.nature.ans.yes": "Да",
  "pack.nature.ans.sometimes": "Иногда",
  "pack.nature.ans.no": "Нет",
  "pack.network.ads.body": "Платная реклама — очень неэффективный способ найти новых психкаров — и способ выбросить наши деньги крупным корпорациям. Намного лучше работает награждать за активность прямо членов движения. Есть один момент: <strong style=\"font-weight:600\">это по-настоящему работает только тогда, когда ты сам идёшь и рассказываешь о нас окружающим</strong> :)",
  "pack.network.ads.header": "Почему именно так?",
