  "pack.network.capped.none": "С этого перевода преданности нет — твои подарки уже сравнялись со всем, что ты прожил. BONES всё равно пройдут. <i>Деньги удваивают годы, но никогда их не заменяют.</i>",
  "pack.network.capped.room": "Ограничено до <b style=\"color:#2a1608\">{room}</b> — подарок может сравняться только с тем, что ты прожил ({lived} преданности пока). BONES всё равно пройдут; честь ждёт дней.",
