  "pack.network.groupTheirBrings": "их приглашения",
  "pack.network.inLine": "В твоей линии",
  "pack.network.info.bones.body": "BONES — внутренняя валюта DOGYPT — игривое название для реальной вещи. Собака платит костями; мы тоже. Ты <b>зарабатываешь</b> их, приводя психкаров в стаю и продвигая движение вперёд, а <b>тратишь</b> их внутри DOGYPT: поддерживая сборы для приютов, получая мерч, а позже оплачивая другим Догиптянам то, что они создают. <b>{n} BONES = 1 €.</b>",
  "pack.network.info.bones.cap": "Что такое BONES?",
  "pack.network.info.why.body": "Движение такого размера нельзя купить — никакой бюджет не достигает незнакомца так, как один Догиптянин достигает друга. Поэтому стая отдаёт награду туда, где есть охват, — тебе. Когда кто-то присоединяется через твою ссылку, ты получаешь <b>{l1} BONES</b>; когда он приводит кого-то ещё, ты получаешь ещё <b>{l2}</b>. Каждый Догиптянин, который распространяет весть, не продавец — он миссионер, и мы ценим эту работу.",
  "pack.network.info.why.cap": "Почему мы просим тебя",
  "pack.network.intro": "Движение растёт только тогда, когда его участники разносят послание и приводят новых людей. Поэтому мы просим тебя напрямую: <strong style=\"color:#2a1608;font-weight:600\">пригласи психкаров, которых ты знаешь</strong>. Вот как это работает, точно.",
